TLM.f("Sancti/06-05",{"officium":"S. Bonifatii Episcopi et Martyris","rule":["Evangelium non appropriatum","vide C2;","Gloria"],"fallback":"Commune/C2","from":{"Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Is 65:19; 65:23"},{"k":"text","la":"Exsultábo in Jerúsalem et gaudébo in pópulo meo: et non audiétur in eo ultra vos fletus et vox clamóris. Elécti mei non laborábunt frustra neque generábunt in conturbatióne: quia semen benedictórum Dómini est, et nepótes eórum cum eis."},{"k":"ref","la":"Ps 43:2"},{"k":"text","la":"Deus, áuribus nostris audívimus: patres nostri narravérunt opus, quod operátus es in diébus eórum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Exsultábo in Jerúsalem et gaudébo in pópulo meo: et non audiétur in eo ultra vos fletus et vox clamóris. Elécti mei non laborábunt frustra neque generábunt in conturbatióne: quia semen benedictórum Dómini est, et nepótes eórum cum eis."}],"Oratio":[{"k":"text","la":"Deus, qui multitúdinem populórum, beáti Bonifátii Mártyris tui atque Pontíficis zelo, ad agnitiónem tui nóminis vocáre dignátus es: concéde propítius; ut, cujus sollémnia cólimus, étiam patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 44:1-15"},{"k":"text","la":"Laudémus viros gloriósos et paréntes nostros in generatióne sua. Multam glóriam fecit Dóminus magnificéntia sua a sǽculo. Dominántes in potestátibus suis, hómines magni virtúte et prudéntia sua præditi, nuntiántes in prophétis dignitátem prophetárum, et imperántes in præsénti pópulo, et virtúte prudéntiæ pópulis sanctíssima verba. In perítia sua requiréntes modos músicos, et narrántes cármina scripturárum. Hómines dívites in virtúte, pulchritúdinis stúdium habéntes: pacificántes in dómibus suis. Omnes isti in generatiónibus gentis suæ glóriam adépti sunt, et in diébus suis habéntur in láudibus. Qui de illis nati sunt, reliquérunt nomen narrándi laudes eórum. Et sunt, quorum non est memória: periérunt, quasi qui non fúerint: et nati sunt, quasi non nati, et fílii ipsórum cum ipsis. Sed illi viri misericórdiæ sunt, quorum pietátes non defuérunt: cum sémine eórum pérmanent bona, heréditas sancta nepótes eórum, et in testaméntis stetit semen eórum: et fílii eórum propter illos usque in ætérnum manent: semen eórum et glória eórum non derelinquétur. Córpora ipsórum in pace sepúlta sunt, et nomen eórum vivit in generatiónem et generatiónem. Sapiéntiam ipsórum narrent pópuli, et laudem eórum núntiet Ecclésia."}],"Graduale":[{"k":"ref","la":"1 Pet 4:13-14"},{"k":"text","la":"Communicántes Christi passiónibus gaudéte, ut in revelatióne glóriæ ejus gaudeátis exsultántes."},{"k":"text","la":"Si exprobrámini in nómine Christi, beáti éritis: quóniam, quod est honóris, glóriæ et virtútis Dei, et qui est ejus Spíritus, super vos requiéscet. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Is 66:12"},{"k":"text","la":"Declinábo super eum quasi flúvium pacis, et quasi torréntem inundántem glóriam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Is 66:10; 66:14"},{"k":"text","la":"Lætámini cum Jerúsalem, et exsultáte in ea, omnes, qui dilígitis Dóminum. Allelúja."},{"k":"text","la":"Vidébitis, et gaudébit cor vestrum: cognoscétur manus Dómini servis ejus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:1-12"},{"k":"text","la":"In illo témpore: Videns Jesus turbas, ascéndit in montem, et cum sedísset, accessérunt ad eum discípuli ejus, et apériens os suum, docébat eos, dicens: Beáti páuperes spíritu: quóniam ipsórum est regnum cœlórum. Beáti mites: quóniam ipsi possidébunt terram. Beáti, qui lugent: quóniam ipsi consolabúntur. Beáti, qui esúriunt et sítiunt justítiam: quóniam ipsi saturabúntur. Beáti misericórdes: quóniam ipsi misericórdiam consequántur. Beáti mundo corde: quóniam ipsi Deum vidébunt. Beáti pacífici: quóniam fílii Dei vocabúntur. Beáti, qui persecutiónem patiúntur propter justítiam: quóniam ipsórum est regnum cœlórum. Beáti estis, cum maledíxerint vobis et persecúti vos fúerint, et díxerint omne malum advérsum vos, mentiéntes, propter me: gaudete et exsultáte, quóniam merces vestra copiósa est in cœlis."}],"Offertorium":[{"k":"ref","la":"Ps 15:7; 15:8"},{"k":"text","la":"Benedícam Dóminum, qui tríbuit mihi intelléctum: providébam Deum in conspéctu meo semper, quóniam a dextris est mihi ne commóvear. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Super has hóstias, Dómine, quǽsumus, benedíctio copiósa descéndat: quæ et sanctificatiónem nostram misericórditer operátur; et de sancti Bonifátii Mártyris tui atque Pontíficis fáciat sollemnitáte gaudére."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Apoc 3:21"},{"k":"text","la":"Qui vícerit, dabo ei sedére mecum in throno meo: sicut et ego vici et sedi cum Patre meo in throno ejus. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Sanctificáti, Dómine, salutári mystério: quǽsumus; ut nobis sancti Bonifátii Mártyris tui atque Pontíficis pia non desit orátio, cujus nos donásti patrocínio gubernári."},{"k":"macro","name":"Per Dominum"}]},"hr":{"cdec95e6fdec686d":{"t":"Iz 65, 19 i 23, Ps 43, 2\n(Iz 65, 19 i 23) Kličem od radosti radi Jeruzalema i veselim se radi puka svoga. Neće se više čuti u njemu glas plača ni glas jauka. Odabranici moji neće se truditi uzalud, niti će rađati djecu za nečastan svršetak, jer su oni rod blagoslovljen od Gospodina i njihovi potomci zajedno s njima. (Ps 43, 2) Bože, ušima smo svojim slušali, oci naši su nam pripovijedali.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 65, 19 i 23) Kličem od radosti radi Jeruzalema i veselim se radi puka svoga. Neće se više čuti u njemu glas plača ni glas jauka. Odabranici moji neće se truditi uzalud, niti će rađati djecu za nečastan svršetak, jer su oni rod blagoslovljen od Gospodina i njihovi potomci zajedno s njima.","kn":"(is. 65. 19. 23). Kličem radi Jeruzalema i radujem se puka moga radi; više da se ne čuje plač r vapaj. Izabrani moji ne će raditi uzalud i ne će Mijati u nevolji, jer oni su pokoljenje blagosloveno . Gospodina sve do unuka njihovih (aleluja aleluja). (Ps. 43, 2). Bože, ušima smo svojim čuli. oci su nam naši pripovijedali djelo, što si učinio u danima njihovim. Slava Ocu . . . Kličem .","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"},"5e9e3ac2a1b8bfe3":{"t":"<i>Pomolimo se</i>.\nBože koji si se udostojao pozvati mnoge narode revnošću blaženog Bonifacija mučenika svoga i biskupa na priznavanje tvoga imena, daj milostiv da osjećamo i zaštitu onoga kojeg svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si mnoštvo' naroda revnošću da mučenikfe i biskupa, pozvao da spoznaju Tvoje ime, dopusti milostivo da osjetimo zagovor onoga, kojega svečanost sla^L ^ Sv. Bonifacije 5.. VI.","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"},"9ed88ae9d6e4eabf":{"t":"Sir 44, 1-15\nČitanje knjige Mudrosti. Hvalimo slavne muževe, naše pretke, jer pripadamo njihovu rodu. Gospodin im je svojom moći od vijeka pribavio Veliku slavu. Vladali su u svojim kraljevstvima, bili su velikani obdareni razboritošću, nastupali su proročkim dostojanstvom, vodili su narod svojega vremena, posebnom su mudrošću predali narodima nauku Svetosti. Bili su vješti izumitelji skladnih popijevaka i ispjevali nadahnute pjesme. Bogati krepostima, uživala su u ljepoti i čuvali mir u: svojim kućama. Prestigli su slavom svoje suvremenike i bit će čašćeni od budućih naraštaja, jer su svojim potomcima ostavili časno ime, da mogu propovijedati njihovu slavu. A ima ljudi kojima nema spomena. Nestalo ih je kao da se nisu ni rodili, ni oni, ni njihova djeca. Oni prvi su ljudi ljubitelji braće i djela njihova milosrđa neće nestati. Dobra im djela ostaju potomstvu. I radi njih će vječno ostati njihova djeca. I neće nestati ni njihova roda, ni njihove slave! Tjelesa su im sahranjena u miru, a njihovo će ime živjeti od koljena do koljena. Neka narodi govore o njihovoj mudrosti, a crkva neka razglašuje njihovu hvalu!","kn":"Čitanje Knjige mudrosti (Crkv. 44, 1-15). Hvalimo slavne muževe, naše pretke, čijega smo rode. Go- .spodin im je od vijeka svojom svemogućnošću (pribavio veliku slavu. Vladali su u svojim kraljevstvima, bili su veliki u moći, obdareni razborom, proročkim su dostojanstvom navješćivali u proroštvima, vladali su narodom svoga vremena i velikom mudrošću dali sti narodima nauku svetosti. Bili su vješti, izumili su skladne popijevke i napisali pjesme. Bili su bogati po kreposti, uživali su u ljepoti i živjeli mirno u svojim domovima. Svi su oni slavo-m prestigli svoje suvremenike i bit će čašćeni u svoje vrijeme. Svojim su potomcima c.stavili ime, da mogu propovijedati njihovu slavu, A ima ih, koji nem-aju uspomene. Nestalo ih je, kaoda nijesu ni bili Rođeni, ali kao da se nijesu rodili ni oni ni njihova djeca s njima. Oni prvi su milosrdni muževi i djela njihova milosrđa nijesu nestalia.^ Dobra im djela o.staju s (porodom, njihovi potomci su sveta baština i njihov je rod ostao vjeran zavjetima. I radi njih će vječno postojati njihova djeca, ne će nestati njihova roda ni njihove slave. Tjelesa su im sahranjena u miru, njihovo će inae živjeti od roda do roda. Narodi neka propovijedaju njihovu mudrost i zbor meka navješćuje njihovu slavu.","knRef":"Kniewald 1942, str. 508–509 (snimka 255) (OCR)"},"4c250aaad805216a":{"t":"1 Pt 4, 13-14\nRadujte se što sudjelujete u muci Kristovoj, a kad se objavi njegova slava, radost će vaša biti beskrajna. Blago vama, ako vas grde poradi Kristova imena, jer Božja čast i slava i sila njegova Duha počiva na vama.\n\nIz 66, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nGle, dovodim mir k njemu kao rijeku i slavu kao nabujali potok. <i>Aleluja</i>.","kn":"(I: Petr. 4, 13, 14). Radujte se. što ste zajedničari patnja Kristovih, da se i radujete klikujući, kad se objavi slava njegova. Ako vas grde za ime Kristovo, blago vama, jer Duh slave i Božji počiva u vama.\n\nAleluja, aleluja. (Is. 66, 12). Navest ću na nj kao struju mira i slavu, kao potok prepun, vode, aleluja.","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"},"32b085bad92b1340":{"t":"Mt 5, 1-12\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme, kad vidje Isus mnoštvo naroda, uspne se na goru; i kad sjedne, približiše mu se njegovi učenici. Tada otvori svoja usta i poče ih učiti: Blago siromasima u duhu, jer je njihovo nebesko kraljevstvo! Blago krotkima, jer će baštiniti zemlju! Blago žalosnima, jer će se utješiti! Blago gladnima i žednima pravde, jer će se nasititi! Blago milosrdnima, jer će postići milosrđe! Blago onima, koji su čista srca, jer će gledati Boga! Blago mirotvorcima, jer će se zvati sinovi Božji! Blago progonjenima zbog pravde, jer je njihovo nebesko kraljevstvo! Blago vama, kad vas budu zlostavljali i progonili, i zbog mene lažno govorili svako zlo protiv vas! Radujte se i od radosti kličite, jer vas čeka velika nagrada na nebu!","kn":"t Slijedi sveto evanđelje po Mateju (5, 1-12). U ono vrijeme vidje Isus mnogo naroida, uspne se na goru, i kad je sjeo, prlstupiše mu njegovi uče nici i poče ih poučavati: Blago siromašnima u duhu,, jer je njihovo kraljevstvo nebesko. Blaigo krotnima, jer će postići milosrđe. Blago čistima u srcu, ma, jer će se utješiti. .Blago onima, koji gladuju i žeđaju pravde, jer će se nasititi. Blago milosrdnima, jer će postići milosrđei. Blago čis.tiima u srcu. jer će vidjeti Boga. Blag*o mirotvorcima, jer će se zvati sinovi Boižji. Blago progonjenima radi pravde, jer je njihovo kraljevstvo nebesko. Blago vama, kad vas radi mene budu proklinjali i progonili i lažno govorili svako zl*o protiv vas. Radujte se i veselite se, jer je obilna vaša plaća na nebu.","knRef":"Kniewald 1942, str. 660–661 (snimka 331) (OCR)"},"dd450bc71446c836":{"t":"Ps 15, 7 i 8\nBlagoslivljam Gospodina što mi je dao razum. Uvijek imam Boga pred očima. On mi je s desne strane, neću se pokolebati.","kn":"(Ps. 15, 7, 8). Blagosivam Gospodina, koji mi je dao razum; svagda imam^ pred sobom Gospodina, on mi je s desne strane, da ne posrnem.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"3edd65daa27a9757":{"t":"Sašao, molimo, Gospodine, na ove darove obilni blagoslov, koji neka nas i milosrdno posveti i učini da se radujemo o svetkovini svetog Bonifacija mučenika tvoga i biskupa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, sašao obilati blagoslov nad ove žrtve, djelovao milosrdno u nama naše p^ svećenje i učinio, da se radujemo o blagdanu bi. Bonifacija, Tvoga mučenika i biskupa, po G. n.","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"6c8def7f70918dda":{"t":"Otk 3, 21\nOnome koji pobijedi dat ću da sjedi sa mnom na mojem prijestolju, kao što sam i ja pobijedio i sjedim s Ocem svojim na prijestolju njegovu.","v":"aleluia → ∅","kn":"(Otkr, 3, 21). Tko pobijedi, dat ću mu da sjedi sa mnom na prijestolju mojemu, kao što i ja pobijedih i sjcdoh s Ocem svojim na prijestolju njegovu (aleluja).","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"},"31552b0bbcc2ff47":{"t":"<i>Pomolimo se</i>.\nPosvećeni, Gospodine, spasonosnom tajnom, molimo, da nas pomogne sveti zagovor blaženog Bonifacija mučenika tvoga i biskupa, kojeg si nam darovao kao zaštitnika i vođu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posvećeni, Gospodine, spasonosnim otajstvom, molimo, da uvijek bude uz nas pobožna molitva, bi. Bonifacija, Tvoga mučenika i biskupa. kojega Si nam htio dati kao zaštitnika i vođu po G. n.","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"},"2e2a9a0662a35058":{"t":"Iz 65, 19 i 23, Ps 43, 2\n(Iz 65, 19 i 23) Kličem od radosti radi Jeruzalema i veselim se radi puka svoga. Neće se više čuti u njemu glas plača ni glas jauka. Odabranici moji neće se truditi uzalud, niti će rađati djecu za nečastan svršetak, jer su oni rod blagoslovljen od Gospodina i njihovi potomci zajedno s njima, <i>aleluja</i>, <i>aleluja</i>. (Ps 43, 2) Bože, ušima smo svojim slušali, oci naši su nam pripovijedali.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 65, 19 i 23) Kličem od radosti radi Jeruzalema i veselim se radi puka svoga. Neće se više čuti u njemu glas plača ni glas jauka. Odabranici moji neće se truditi uzalud, niti će rađati djecu za nečastan svršetak, jer su oni rod blagoslovljen od Gospodina i njihovi potomci zajedno s njima, <i>aleluja</i>, <i>aleluja</i>.","v":"∅ → aleluia aleluia; ∅ → aleluia aleluia","kn":"(is. 65. 19. 23). Kličem radi Jeruzalema i radujem se puka moga radi; više da se ne čuje plač r vapaj. Izabrani moji ne će raditi uzalud i ne će Mijati u nevolji, jer oni su pokoljenje blagosloveno . Gospodina sve do unuka njihovih (aleluja aleluja). (Ps. 43, 2). Bože, ušima smo svojim čuli. oci su nam naši pripovijedali djelo, što si učinio u danima njihovim. Slava Ocu . . . Kličem , <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"},"a498a4682cf647f6":{"kn":"Aleluja, aleluja (Is. 66, 10, 14). Radujte se s Jeruzalemom i kličite s njim svi, koji ljubite Gospodina, aleluja. Vidjet ćete i radovat će se srce vaše; pokazat će se ruka Gospodnja službenicima njegovim, aleluja.","knRef":"Kniewald 1942, str. 589"},"311d7f7276b3f7a3":{"t":"Ps 15, 7 i 8\nBlagoslivljam Gospodina što mi je dao razum. Uvijek imam Boga pred očima. On mi je s desne strane, neću se pokolebati, <i>aleluja</i>.","v":"∅ → aleluia","kn":"(Ps. 15, 7, 8). Blagosivam Gospodina, koji mi je dao razum; svagda imam^ pred sobom Gospodina, on mi je s desne strane, da ne posrnem, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, jer On se poslije svoga uskrsnuća očito ukazao svim svojim učenicima 1 njima se na očigled uzđignuo na nebo, da tako, po njegovom daru, budemo zajedničari Božanstva Njegova. I toga radi pjevamo pjesmu slave Tvoje s anđelima i B arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"4a59355aa53643a5":{"t":"Otk 3, 21\nOnome koji pobijedi dat ću da sjedi sa mnom na mojem prijestolju, kao što sam i ja pobijedio i sjedim s Ocem svojim na prijestolju njegovu. <i>Aleluja</i>.","kn":"(Otkr, 3, 21). Tko pobijedi, dat ću mu da sjedi sa mnom na prijestolju mojemu, kao što i ja pobijedih i sjcdoh s Ocem svojim na prijestolju njegovu (aleluja), <i>aleluja</i>.","knRef":"Kniewald 1942, str. 588–589 (snimka 295) (OCR)"}}});
